<?php $esc=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$data=static fn($v):string=>($t=strtotime((string)$v))?date('d/m/Y H:i',$t):'—';$loja=trim((string)($pedido['cliente_nome_fantasia']??''))?:trim((string)($pedido['cliente_razao_social']??'')); ?>
<style>.detail-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:20px}.detail-title h2{margin:0 0 5px}.detail-title p{margin:0;color:var(--text-muted)}.detail-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}.detail-card{padding:15px;border:1px solid var(--border);border-radius:15px;background:var(--surface-muted)}.detail-card small{display:block;color:var(--text-muted);margin-bottom:5px}.detail-card strong{font-size:1rem}.signature-detail{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}.signature-detail article{padding:17px;border:1px solid var(--border);border-radius:16px}.signature-detail h3{margin:0 0 4px}.signature-detail p{margin:0 0 12px;color:var(--text-muted)}.signature-detail img{display:block;width:100%;height:150px;object-fit:contain;border:1px dashed var(--border);border-radius:12px;background:#fff}@media(max-width:900px){.detail-grid{grid-template-columns:1fr 1fr}}@media(max-width:650px){.detail-grid,.signature-detail{grid-template-columns:1fr}.detail-head{flex-direction:column}}</style>
<section class="panel"><header class="detail-head"><div class="detail-title"><h2>Romaneio <?= $esc($expedicao['romaneio']??'—'); ?></h2><p>Detalhes completos da expedição e comprovantes de assinatura.</p></div><a class="button button-outline" href="<?= $esc($url('expedicao?tab=concluidos')); ?>">Voltar</a></header>
<div class="detail-grid"><div class="detail-card"><small>Pedido</small><strong><?= $esc($pedido['codigo']??'#'.$pedido['id']); ?></strong></div><div class="detail-card"><small>Loja</small><strong><?= $esc($loja?:'Não identificada'); ?></strong></div><div class="detail-card"><small>Data da expedição</small><strong><?= $esc($data($expedicao['data_expedicao']??'')); ?></strong></div><div class="detail-card"><small>Data da separação</small><strong><?= $esc($data($expedicao['data_separacao']??'')); ?></strong></div><div class="detail-card"><small>Volumes</small><strong><?= (int)($expedicao['volumes']??0); ?></strong></div><div class="detail-card"><small>Peso total</small><strong><?= number_format((float)($expedicao['peso_total']??0),3,',','.'); ?> kg</strong></div><div class="detail-card"><small>Tipo de entrega</small><strong><?= strtolower((string)($expedicao['tipo_entrega']??'propria'))==='terceiros'?'Transportadora terceirizada':'Entrega própria'; ?></strong></div><div class="detail-card"><small>Transportadora</small><strong><?= $esc($expedicao['transportadora']?:'Não informada'); ?></strong></div><div class="detail-card"><small>Status</small><strong><?= !empty($expedicao['data_recebimento'])?'Entregue':'Expedido'; ?></strong></div></div>
<div style="overflow-x:auto"><table class="data-table"><thead><tr><th>Produto</th><th>SKU</th><th>Quantidade</th><th>Peso unitário</th><th>Peso total</th></tr></thead><tbody><?php foreach($itens as $item):?><tr><td><strong><?= $esc($item['nome']??'Produto'); ?></strong></td><td><?= $esc($item['sku']??'—'); ?></td><td><?= number_format((float)($item['quantidade']??0),4,',','.'); ?> <?= $esc($item['unidade']??''); ?></td><td><?= number_format((float)($item['peso_liquido']??0),3,',','.'); ?> kg</td><td><?= number_format((float)($item['quantidade']??0)*(float)($item['peso_liquido']??0),3,',','.'); ?> kg</td></tr><?php endforeach;?></tbody></table></div>
<div class="signature-detail"><article><h3>Motorista</h3><p><?= $esc($expedicao['motorista_nome']?:'Não informado'); ?></p><?php if(!empty($expedicao['assinatura_motorista'])):?><img src="<?= $esc($expedicao['assinatura_motorista']); ?>" alt="Assinatura do motorista"><?php else:?><p>Assinatura não registrada.</p><?php endif;?></article><article><h3>Responsável pela expedição</h3><p><?= $esc($expedicao['responsavel_expedicao_nome']?:'Não informado'); ?></p><?php if(!empty($expedicao['assinatura_responsavel'])):?><img src="<?= $esc($expedicao['assinatura_responsavel']); ?>" alt="Assinatura do responsável"><?php else:?><p>Assinatura não registrada.</p><?php endif;?></article><?php if(!empty($expedicao['data_recebimento'])):?><article><h3>Responsável pelo recebimento</h3><p><?= $esc($expedicao['recebedor_nome']?:'Não informado'); ?> · <?= $esc($data($expedicao['data_recebimento'])); ?></p><?php if(!empty($expedicao['assinatura_recebedor'])):?><img src="<?= $esc($expedicao['assinatura_recebedor']); ?>" alt="Assinatura do recebimento"><?php endif;?><?php if(!empty($expedicao['observacao_recebimento'])):?><p><?= $esc($expedicao['observacao_recebimento']); ?></p><?php endif;?></article><?php endif;?><?php if(!empty($expedicao['data_confirmacao_cliente'])):?><article class="portal-receipt-confirmation"><h3>Pedido confirmado como recebido via portal</h3><p>Confirmação registrada pelo cliente.</p><div class="detail-card"><small>Data e hora da confirmação</small><strong><?= $esc($data($expedicao['data_confirmacao_cliente'])); ?></strong></div></article><?php endif;?></div></section>
<script>
(()=>{const crop=image=>{if(!image.naturalWidth||!image.naturalHeight)return;const scale=Math.min(1,1200/image.naturalWidth,700/image.naturalHeight),width=Math.max(1,Math.round(image.naturalWidth*scale)),height=Math.max(1,Math.round(image.naturalHeight*scale)),source=document.createElement('canvas');source.width=width;source.height=height;const context=source.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,width,height);const pixels=context.getImageData(0,0,width,height).data;let left=width,top=height,right=-1,bottom=-1;for(let y=0;y<height;y++){for(let x=0;x<width;x++){const index=(y*width+x)*4,alpha=pixels[index+3],dark=pixels[index]+pixels[index+1]+pixels[index+2]<690;if(alpha>18&&dark){if(x<left)left=x;if(x>right)right=x;if(y<top)top=y;if(y>bottom)bottom=y}}}if(right<left||bottom<top)return;const padding=Math.max(10,Math.round(Math.max(right-left,bottom-top)*.08)),cropWidth=right-left+1,cropHeight=bottom-top+1,target=document.createElement('canvas');target.width=cropWidth+padding*2;target.height=cropHeight+padding*2;target.getContext('2d').drawImage(source,left,top,cropWidth,cropHeight,padding,padding,cropWidth,cropHeight);image.src=target.toDataURL('image/png');image.classList.add('is-framed')};document.querySelectorAll('.signature-detail img').forEach(image=>image.complete?crop(image):image.addEventListener('load',()=>crop(image),{once:true}))})();
</script>
